const PANEL: Panel = /*PANEL*/ {
  name: '__MOD__',
  description: '',
  title: 'Panel',
  command: '__CMD__',
  openOnStart: false,
  refreshSec: 5,
  band: false,
  widgets: [],
} /*END*/

const PANE = '__MOD__'
const TOOL_PREFIX = 'mcp____MOD____'

const S_agents = atom({ plugin: '__MOD__', key: 'agents' } as const, [])
const S_tools = atom({ plugin: '__MOD__', key: 'tools' } as const, [])
const S_usage = atom({ plugin: '__MOD__', key: 'usage' } as const, null)
const S_git = atom({ plugin: '__MOD__', key: 'git' } as const, null)
const S_peers = atom({ plugin: '__MOD__', key: 'peers' } as const, [])
const S_info = atom({ plugin: '__MOD__', key: 'info' } as const, null)
const S_outputs = atom({ plugin: '__MOD__', key: 'outputs' } as const, {})
const S_drafts = atom({ plugin: '__MOD__', key: 'drafts' } as const, {})
const S_flash = atom({ plugin: '__MOD__', key: 'flash' } as const, '')
const S_expanded = atom({ plugin: '__MOD__', key: 'expanded' } as const, {})
const S_messages = atom({ plugin: '__MOD__', key: 'messages' } as const, [])
const S_inventory = atom({ plugin: '__MOD__', key: 'inventory' } as const, null)
const S_turn = atom({ plugin: '__MOD__', key: 'turn' } as const, null)
const S_ctxHistory = atom({ plugin: '__MOD__', key: 'ctxHistory' } as const, [])
const S_counters = atom({ plugin: '__MOD__', key: 'counters' } as const, {})
const S_toggles = atom({ plugin: '__MOD__', key: 'toggles' } as const, {})
const S_notes = atom({ plugin: '__MOD__', key: 'notes' } as const, {})

type Of<K extends Widget['kind']> = Extract<Widget, { kind: K }>
const has = (kind: Widget['kind']) => PANEL.widgets.some(w => w.kind === kind)
const ofKind = <K extends Widget['kind']>(kind: K) => PANEL.widgets.filter((w): w is Of<K> => w.kind === kind)
const ENDED = ['completed', 'failed', 'killed']
const GLYPH: Record<string, string> = { running: '◐', pending: '○', waiting: '●', idle: '◌', completed: '✓', failed: '✗', killed: '✗' }

// ── formatting ─────────────────────────────────────────────

function dur(ms: number): string {
  const s = Math.max(0, Math.round(ms / 1000))
  if (s < 60) return `${s}s`
  const m = Math.floor(s / 60)
  if (m < 60) return `${m}m ${s % 60}s`
  return `${Math.floor(m / 60)}h ${m % 60}m`
}

function tok(n: number | undefined): string {
  if (n === undefined) return '?'
  if (n < 1000) return String(n)
  if (n < 1_000_000) return `${Math.round(n / 1000)}k`
  return `${(n / 1_000_000).toFixed(1)}M`
}

function bar(pct: number, width = 16): string {
  const full = Math.round((Math.min(100, Math.max(0, pct)) / 100) * width)
  return '█'.repeat(full) + '░'.repeat(width - full)
}

function sparkline(values: number[]): string {
  const ticks = '▁▂▃▄▅▆▇█'
  return values.map(v => ticks[Math.min(7, Math.max(0, Math.floor((v / 100) * 8)))]).join('')
}

function tilde(path: string, home: string | undefined): string {
  return home && path.startsWith(home) ? '~' + path.slice(home.length) : path
}

function shq(s: string): string {
  return `'${s.replace(/'/g, `'\\''`)}'`
}

function clip(s: string, n: number): string {
  const t = s.replace(/\s+/g, ' ').trim()
  return t.length > n ? t.slice(0, n - 1) + '…' : t
}

/** `a.b[0].c` into a parsed JSON value. */
function pick(value: unknown, path: string): unknown {
  if (!path.trim()) return value
  let cur: unknown = value
  for (const part of path.replace(/\[(\d+)\]/g, '.$1').split('.').filter(Boolean)) {
    if (cur === null || typeof cur !== 'object') return undefined
    cur = (cur as Record<string, unknown>)[part]
  }
  return cur
}

const show = (v: unknown) => (v === undefined ? '—' : typeof v === 'object' ? JSON.stringify(v) : String(v))

// ── data ───────────────────────────────────────────────────

async function flash($: EngineInterface, text: string) {
  await update($, S_flash, () => text)
}

async function setOutput($: EngineInterface, id: string, text: string) {
  await update($, S_outputs, o => ({ ...o, [id]: text }))
}

async function isOn($: EngineInterface, id: string) {
  return (await read($, S_toggles))[id] !== false
}

async function refreshAgents($: EngineInterface) {
  const keepMs = (ofKind('agents')[0]?.keepMinutes ?? 15) * 60_000
  const now = await $.clock.now()
  let listed: { id: string; description: string; type: string; status: string }[] = []
  try {
    listed = await $.agent.list()
  } catch {
    return
  }
  await update($, S_agents, prev => {
    const byId = new Map(prev.map(a => [a.id, a] as const))
    const next: AgentRow[] = []
    for (const l of listed) {
      const old = byId.get(l.id)
      const ended = ENDED.includes(l.status)
      next.push({
        ...(old ?? { steps: 0, tools: 0, outTokens: 0, ctxTokens: 0, firstSeenMs: now }),
        id: l.id,
        description: l.description,
        type: l.type,
        status: l.status,
        ...(ended ? { endedMs: old?.endedMs ?? now } : {}),
      })
      byId.delete(l.id)
    }
    for (const gone of byId.values()) next.push({ ...gone, endedMs: gone.endedMs ?? now })
    return next.filter(a => !a.endedMs || now - a.endedMs < keepMs)
  })
}

async function refreshUsage($: EngineInterface) {
  try {
    const u = await $.session.usage()
    const pct = u.context.percent ?? (u.context.tokens !== undefined ? (u.context.tokens / u.context.window) * 100 : undefined)
    await update($, S_usage, () => ({
      startedAt: u.startedAt,
      tokens: u.context.tokens,
      window: u.context.window,
      percent: pct,
      usd: u.cost?.usd,
      limits: u.rateLimits.map(l => ({ kind: l.kind, percentUsed: l.percentUsed, resetsAt: l.resetsAt })),
    }))
    if (pct !== undefined && has('contextChart')) {
      const keep = Math.max(...ofKind('contextChart').map(w => w.points), 10)
      await update($, S_ctxHistory, h => (h[h.length - 1] === pct ? h : [...h, pct].slice(-keep)))
    }
  } catch {
    /* not available on this surface */
  }
}

async function refreshInfo($: EngineInterface) {
  const [model, turns, cwd, sessionId] = await Promise.all([$.session.model(), $.session.turns(), $.session.cwd(), $.session.id()])
  await update($, S_info, () => ({ model, turns, cwd, sessionId }))
}

async function refreshGit($: EngineInterface) {
  const cwd = await $.session.cwd()
  const [st, log] = await Promise.all([
    $.process.run(['git', '-C', cwd, 'status', '--porcelain=v1', '-b'], { timeoutMs: 5000 }),
    $.process.run(['git', '-C', cwd, 'log', '-1', '--format=%h %s · %cr'], { timeoutMs: 5000 }),
  ])
  if (st.exitCode !== 0) {
    await update($, S_git, () => ({ branch: '', ahead: 0, behind: 0, files: [], last: '', error: st.stderr.trim().split('\n')[0] ?? 'not a git repo' }))
    return
  }
  const [head = '', ...files] = st.stdout.split('\n').filter(Boolean)
  const branch = head.replace(/^## /, '').split('...')[0] ?? ''
  const row: GitRow = {
    branch: branch.replace('No commits yet on ', ''),
    ahead: Number(head.match(/ahead (\d+)/)?.[1] ?? 0),
    behind: Number(head.match(/behind (\d+)/)?.[1] ?? 0),
    files,
    last: log.stdout.trim(),
  }
  await update($, S_git, () => row)
}

async function refreshDiff($: EngineInterface, w: Of<'diff'>) {
  const cwd = await $.session.cwd()
  const r = await $.process.run(['git', '-C', cwd, 'diff', '--no-color'], { timeoutMs: 8000 })
  const lines = r.stdout.split('\n')
  let text = lines.slice(0, w.maxLines).join('\n')
  // cut at the last whole hunk so it still parses as a diff
  if (lines.length > w.maxLines) text = text.slice(0, Math.max(0, text.lastIndexOf('\n@@'))) || text
  await setOutput($, w.id, r.exitCode === 0 ? text : `!${r.stderr.trim()}`)
}

async function refreshPeers($: EngineInterface) {
  const home = await $.env.get('HOME')
  if (!home) return
  const dir = `${home}/.claude/sessions`
  const self = await $.session.id()
  const rows: PeerRow[] = []
  try {
    for (const f of await $.fs.list(dir)) {
      if (!f.name.endsWith('.json')) continue
      try {
        const j = JSON.parse(await $.fs.read(`${dir}/${f.name}`)) as Record<string, unknown>
        rows.push({
          pid: Number(j.pid),
          sessionId: String(j.sessionId ?? ''),
          name: String(j.name ?? j.sessionId ?? f.name),
          cwd: String(j.cwd ?? ''),
          status: String(j.status ?? ''),
          kind: String(j.kind ?? ''),
          updatedAt: Number(j.updatedAt ?? f.mtimeMs),
          isSelf: j.sessionId === self,
        })
      } catch {
        /* a file mid-write */
      }
    }
  } catch (err) {
    await setOutput($, 'peers', `Cannot read ${dir}: ${String(err)}`)
    return
  }
  const pids = rows.map(r => r.pid).filter(p => p > 0)
  if (pids.length) {
    const ps = await $.process.run(['ps', '-o', 'pid=', '-p', pids.join(',')], { timeoutMs: 3000 })
    const alive = new Set(ps.stdout.split('\n').map(s => Number(s.trim())).filter(Boolean))
    await update($, S_peers, () => rows.filter(r => alive.has(r.pid)).sort((a, b) => b.updatedAt - a.updatedAt))
  } else {
    await update($, S_peers, () => [])
  }
}

async function refreshMessages($: EngineInterface) {
  const keep = Math.max(...ofKind('messages').map(w => w.count), 1)
  const list = await $.session.messages()
  const rows: MsgRow[] = list
    .filter(m => m.text.trim() || m.toolUses.length)
    .slice(-keep)
    .map(m => ({ role: m.role, text: clip(m.text, 400), tools: m.toolUses.map(t => String((t as { name?: string }).name ?? 'tool')) }))
  await update($, S_messages, () => rows)
}

async function refreshInventory($: EngineInterface) {
  const [tools, commands] = await Promise.all([$.tool.list(), $.command.list()])
  await update($, S_inventory, () => ({
    tools: tools.map(t => ({ name: t.name, mcp: t.mcp })),
    commands: commands.map(c => ({ name: c.name, description: c.description })).sort((a, b) => a.name.localeCompare(b.name)),
  }))
}

async function cwdPath($: EngineInterface, path: string): Promise<string> {
  if (path.startsWith('/')) return path
  if (path.startsWith('~/')) return `${(await $.env.get('HOME')) ?? ''}${path.slice(1)}`
  return `${await $.session.cwd()}/${path}`
}

async function refreshShell($: EngineInterface, w: Of<'shell'>) {
  const r = await $.process.run(['sh', '-c', w.command], { cwd: await $.session.cwd(), timeoutMs: 15_000 })
  const text = (r.stdout + (r.exitCode !== 0 ? r.stderr : '')).trimEnd().split('\n').slice(-w.lines).join('\n')
  await setOutput($, w.id, text || '(empty)')
}

async function refreshFile($: EngineInterface, w: Of<'file'>) {
  let text: string
  try {
    text = (await $.fs.read(await cwdPath($, w.path))).split('\n').slice(0, w.lines).join('\n')
  } catch {
    text = `no file ${w.path}`
  }
  await setOutput($, w.id, text)
}

async function refreshHttp($: EngineInterface, w: Of<'http'>) {
  try {
    const r = await $.http.fetch(w.url, { ...(w.auth ? { headers: { Authorization: w.auth } } : {}) })
    let value: string
    try {
      value = show(pick(JSON.parse(r.text), w.jsonPath))
    } catch {
      value = clip(r.text, 300)
    }
    await setOutput($, w.id, `${r.status} · ${value}`)
  } catch (err) {
    await setOutput($, w.id, `error: ${String(err)}`)
  }
}

async function refreshMcp($: EngineInterface, w: Of<'mcp'>) {
  try {
    const args = w.args.trim() ? (JSON.parse(w.args) as Record<string, unknown>) : {}
    const r = await $.mcp.call(w.server, w.tool, args)
    const text = r.content.map(c => c.text ?? c.uri ?? '').filter(Boolean).join('\n') || show(r.structuredContent)
    await setOutput($, w.id, `${r.isError ? '✗ ' : ''}${text}`)
  } catch (err) {
    await setOutput($, w.id, `error: ${String(err)}`)
  }
}

async function loadNotes($: EngineInterface) {
  for (const w of ofKind('notes')) {
    const saved = await $.store.get(`notes:${w.id}`)
    if (Array.isArray(saved)) await update($, S_notes, n => ({ ...n, [w.id]: saved.map(String) }))
  }
}

async function setNotes($: EngineInterface, id: string, notes: string[]) {
  await update($, S_notes, n => ({ ...n, [id]: notes }))
  await $.store.set(`notes:${id}`, notes)
}

async function refreshAll($: EngineInterface) {
  const jobs: Promise<unknown>[] = []
  if (has('agents') || PANEL.band) jobs.push(refreshAgents($))
  if (has('usage') || has('session') || has('contextChart') || PANEL.band) jobs.push(refreshUsage($))
  if (has('session')) jobs.push(refreshInfo($))
  if (has('git') || PANEL.band) jobs.push(refreshGit($))
  if (has('sessions')) jobs.push(refreshPeers($))
  for (const w of ofKind('file')) jobs.push(refreshFile($, w))
  await Promise.allSettled(jobs)
}

/** What changes only when a turn ends. */
async function refreshAfterTurn($: EngineInterface) {
  const jobs: Promise<unknown>[] = [refreshAll($)]
  if (has('messages')) jobs.push(refreshMessages($))
  for (const w of ofKind('diff')) jobs.push(refreshDiff($, w))
  await Promise.allSettled(jobs)
}

// ── actions ────────────────────────────────────────────────

async function spawn($: EngineInterface, p: { label: string; type: string; prompt: string; model?: string }) {
  if (!p.prompt.trim()) return flash($, 'Empty prompt: no agent started')
  void $.agent
    .spawn({ prompt: p.prompt, description: p.label || p.prompt.slice(0, 40), subagentType: p.type || 'general-purpose', ...(p.model ? { model: p.model } : {}) })
    .catch((err: unknown) => flash($, `Agent did not start: ${String(err)}`))
  await flash($, `Started agent “${p.label || p.type}”`)
  await $.clock.sleep(400)
  await refreshAgents($)
}

async function openSession($: EngineInterface, w: Of<'newSession'>, prompt: string) {
  const cwd = w.cwd.trim() ? await cwdPath($, w.cwd.trim()) : await $.session.cwd()
  const sh = `cd ${shq(cwd)} && claude${prompt.trim() ? ' ' + shq(prompt.trim()) : ''}`
  const as = JSON.stringify(sh)
  const script =
    w.app === 'iTerm'
      ? `tell application "iTerm"\ncreate window with default profile\ntell current session of current window to write text ${as}\nactivate\nend tell`
      : `tell application "Terminal"\ndo script ${as}\nactivate\nend tell`
  const r = await $.process.run(['osascript', '-e', script], { timeoutMs: 10_000 })
  await flash($, r.exitCode === 0 ? `Opened a new session in ${w.app}` : `Did not open: ${r.stderr.trim()}`)
}

async function askSession($: EngineInterface, id: string, question: string) {
  if (!question.trim()) return
  await setOutput($, id, '… thinking')
  const r = await $.model.fork({ prompt: question })
  await setOutput($, id, r.isAnswered ? r.text : r.reason === 'nothing-to-fork' ? 'No conversation in this session yet.' : `No answer: ${r.reason}`)
}

async function runAi($: EngineInterface, id: string, p: AiPreset) {
  await setOutput($, id, `… ${p.label}`)
  let prompt = p.prompt
  if (p.context.trim()) {
    const ctx = await $.process.run(['sh', '-c', p.context], { cwd: await $.session.cwd(), timeoutMs: 15_000 })
    prompt += `\n\n<context command="${p.context}">\n${ctx.stdout.slice(0, 60_000)}\n</context>`
  }
  const model = p.model || 'haiku'
  const labels = p.labels.split(',').map(s => s.trim()).filter(Boolean)
  if (labels.length) {
    const label = await $.model.classify(prompt, labels, { model })
    await setOutput($, id, label ? `**${label}**` : 'Could not classify')
    return
  }
  const r = await $.model.complete({ model, prompt })
  await setOutput($, id, r.isAnswered ? r.text : `No answer: ${r.reason}`)
}

async function suggestNext($: EngineInterface, w: Of<'nextStep'>) {
  if (!(await isOn($, w.id))) return
  const r = await $.model.fork({ prompt: w.instruction })
  if (!r.isAnswered) return
  const text = r.text.trim().replace(/^["«]|["»]$/g, '')
  await setOutput($, w.id, text)
  await $.prompt.suggest({ text })
}

async function quoteSelection($: EngineInterface) {
  const sel = await $.ui.selection()
  if (!sel) return flash($, 'Nothing selected (selection works in the fullscreen terminal)')
  await $.prompt.fill({ text: sel.text.replace(/^/gm, '> ') + '\n\n', mode: 'insert' })
}

async function runChoice($: EngineInterface, w: Of<'choice'>) {
  const options = w.options.split(',').map(s => s.trim()).filter(Boolean)
  const choice = await $.ui.ask(w.question, { options })
  if (!choice) return
  const text = w.template.split('{{choice}}').join(choice)
  if (w.mode === 'submit') void $.prompt.submit({ text })
  else await $.prompt.fill({ text, mode: 'insert' })
}

async function copy($: EngineInterface, text: string) {
  const r = await $.ui.copy({ text })
  await flash($, r.isCopied ? 'Copied' : `Not copied: ${r.reason ?? ''}`)
}

function toolDetail(input: Record<string, unknown>): string {
  for (const k of ['command', 'file_path', 'pattern', 'url', 'query', 'description', 'prompt', 'path']) {
    const v = input[k]
    if (typeof v === 'string' && v) return v.replace(/\s+/g, ' ')
  }
  return ''
}

// ── hooks ──────────────────────────────────────────────────

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({ name: '__CMD__', description: `Open ${PANEL.title}` })
    for (const w of ofKind('modelTool'))
      await $.tool.register({
        name: w.name,
        description: w.description,
        inputSchema: { type: 'object', properties: { input: { type: 'string', description: 'Argument passed to the command as {{input}}' } } },
        isDeferred: false,
      })
    for (const w of ofKind('agentTypes'))
      for (const a of w.presets)
        await $.agent.register({
          name: a.name,
          description: a.description,
          prompt: a.prompt,
          ...(a.model ? { model: a.model } : {}),
          ...(a.tools.trim() ? { tools: a.tools.split(',').map(s => s.trim()).filter(Boolean) } : {}),
        })
    void refreshAll($)
    if (has('messages')) void refreshMessages($)
    if (has('inventory') || ofKind('commands').some(w => w.picker)) void refreshInventory($)
    if (has('notes')) void loadNotes($)
    for (const w of ofKind('diff')) void refreshDiff($, w)
    $.clock.every(Math.max(1, PANEL.refreshSec) * 1000, () => void refreshAll($))
    for (const w of ofKind('shell')) {
      void refreshShell($, w)
      $.clock.every(Math.max(2, w.everySec) * 1000, () => void refreshShell($, w))
    }
    for (const w of ofKind('http')) {
      void refreshHttp($, w)
      if (w.everySec > 0) $.clock.every(Math.max(5, w.everySec) * 1000, () => void refreshHttp($, w))
    }
    for (const w of ofKind('mcp')) {
      void refreshMcp($, w)
      if (w.everySec > 0) $.clock.every(Math.max(5, w.everySec) * 1000, () => void refreshMcp($, w))
    }
    if (PANEL.openOnStart) void $.ui.open({ id: PANE, title: PANEL.title })
    return next(e)
  })

  on('command.run', { command: '__CMD__' }, async $ => {
    void refreshAll($)
    const placed = await $.ui.open({ id: PANE, title: PANEL.title })
    return { text: placed.isPlaced === false ? `${PANEL.title} waits for room to open.` : `${PANEL.title} opened.` }
  })

  on('turn.start', async ($, e, next) => {
    const r = await next(e)
    if (!e.agentId) {
      const now = await $.clock.now()
      await update($, S_turn, () => ({ id: e.turnId, startedMs: now }))
    }
    return r
  })

  on('turn.complete', async ($, e, next) => {
    if (e.agentId) return next(e)
    const turn = await read($, S_turn)
    await update($, S_turn, () => null)
    void refreshAfterTurn($)
    const took = turn ? ((await $.clock.now()) - turn.startedMs) / 1000 : 0
    for (const w of ofKind('voice')) {
      if (took < w.minSeconds || !(await isOn($, w.id))) continue
      if (w.speak.trim()) void $.audio.speak(w.speak).catch(() => undefined)
      if (w.notify) void $.ui.notify(`${w.speak || 'Done'} · ${dur(took * 1000)}`, { title: PANEL.title })
    }
    if (e.reason === 'answer') for (const w of ofKind('nextStep')) void suggestNext($, w)
    return next(e)
  })

  // a subagent's model steps: output tokens add up, the input is its context now
  on('turn.step', async function* ($, e, next) {
    const r = yield* next(e)
    const id = e.agentId
    const u = (r as { usage?: { input_tokens?: number; output_tokens?: number; cache_read_input_tokens?: number; cache_creation_input_tokens?: number } | null } | undefined)?.usage
    if (id && u && has('agents')) {
      const ctx = (u.input_tokens ?? 0) + (u.cache_read_input_tokens ?? 0) + (u.cache_creation_input_tokens ?? 0)
      await update($, S_agents, list =>
        list.map(a => (a.id === id ? { ...a, steps: a.steps + 1, outTokens: a.outTokens + (u.output_tokens ?? 0), ctxTokens: ctx, model: e.model } : a)),
      )
    }
    return r
  })

  // the Agent call's result has the engine's own totals for the subagent it ran
  on('tool.call', { tool: 'Agent' }, async ($, e, next) => {
    const r = await next(e)
    const res = (r as { result?: { agentId?: string; totalTokens?: number; totalDurationMs?: number } }).result
    if (res?.agentId && has('agents')) {
      const id = res.agentId
      await update($, S_agents, list =>
        list.map(a =>
          a.id === id
            ? { ...a, ...(res.totalTokens !== undefined ? { totalTokens: res.totalTokens } : {}), ...(res.totalDurationMs !== undefined ? { durationMs: res.totalDurationMs } : {}) }
            : a,
        ),
      )
      void refreshAgents($)
    }
    return r
  })

  // guards, the panel's own tools for the model, and the tool-call log
  on('tool.call', async ($, e, next) => {
    const tool = String(e.tool)
    const input = e as unknown as Record<string, unknown>
    const detail = toolDetail(input)

    for (const w of ofKind('guard')) {
      if (!(await isOn($, w.id))) continue
      for (const rule of w.rules) {
        const toolMatches = !rule.tool.trim() || rule.tool.trim() === '*' || rule.tool.trim() === tool
        let hit = false
        try {
          hit = toolMatches && !!rule.pattern && new RegExp(rule.pattern).test(detail)
        } catch {
          hit = false
        }
        if (hit) {
          await update($, S_counters, c => ({ ...c, [w.id]: (c[w.id] ?? 0) + 1 }))
          return { deny: `${PANEL.name}: ${rule.reason || 'blocked by a rule'}` }
        }
      }
    }

    const own = ofKind('modelTool').find(w => tool === TOOL_PREFIX + w.name)
    if (own) {
      await update($, S_counters, c => ({ ...c, [own.id]: (c[own.id] ?? 0) + 1 }))
      const arg = String(input.input ?? '')
      const r = await $.process.run(['sh', '-c', own.command.split('{{input}}').join(shq(arg))], { cwd: await $.session.cwd(), timeoutMs: 60_000 })
      const text = (r.stdout + (r.exitCode !== 0 ? `\n[exit ${r.exitCode}] ${r.stderr}` : '')).slice(0, 50_000) || '(no output)'
      return { result: text, text }
    }

    const now = await $.clock.now()
    if (e.agentId && has('agents')) {
      const id = e.agentId
      await update($, S_agents, list => list.map(a => (a.id === id ? { ...a, tools: a.tools + 1, lastTool: tool } : a)))
    }
    if (!has('tools')) return next(e)
    const row: ToolRow = { id: e.tool_use_id, tool, detail, startedMs: now, ...(e.agentId ? { agentId: e.agentId } : {}) }
    await update($, S_tools, list => [...list, row].slice(-60))
    const r = await next(e)
    const ended = await $.clock.now()
    const denied = r.deny !== undefined
    const isError = !denied && r.isError === true
    await update($, S_tools, list => list.map(t => (t.id === row.id ? { ...t, endedMs: ended, isError, denied } : t)))
    return r
  })

  if (has('systemPrompt'))
    on('prompt.compose', async ($, e, next) => {
      const r = await next(e)
      const toggles = await read($, S_toggles)
      const added = ofKind('systemPrompt')
        .filter(w => toggles[w.id] !== false && w.text.trim())
        .map(w => ({ id: `${PANEL.name}:${w.id}`, text: w.text, scope: 'session' as const }))
      return added.length ? { ...r, sections: [...r.sections, ...added] } : r
    })

  // ── drawing ──
  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const el = $.ui.resolve(e)
    const { Box, Text, Button, Markdown, Code, Link } = el
    const Input = 'Input' in el ? el.Input : undefined
    const Select = 'Select' in el ? el.Select : undefined
    const Image = 'Image' in el ? el.Image : undefined
    const now = await $.clock.now()
    const home = await $.env.get('HOME')
    const drafts = await read($, S_drafts)
    const expanded = await read($, S_expanded)
    const outputs = await read($, S_outputs)
    const toggles = await read($, S_toggles)
    const counters = await read($, S_counters)
    const setDraft = (k: string) => (v: string) => void update($, S_drafts, d => ({ ...d, [k]: v }))
    const clearDraft = (k: string) => update($, S_drafts, d => ({ ...d, [k]: '' }))
    const sections: RenderChildren[] = []

    const head = (w: Widget, color: string, extra = '') => (
      <Box key={`${w.id}-h`}>
        <Text bold color={color}>
          {w.title}
          {extra}
        </Text>
      </Box>
    )
    const toggle = (w: Widget, onLabel = 'on', offLabel = 'off') => {
      const enabled = toggles[w.id] !== false
      return (
        <Button
          key={`${w.id}-tg`}
          label={enabled ? `● ${onLabel}` : `○ ${offLabel}`}
          plain
          onPress={() => void update($, S_toggles, t => ({ ...t, [w.id]: !enabled }))}
        />
      )
    }
    /** An AI answer with buttons to copy it or put it into the prompt. */
    const answer = (w: Widget): RenderChildren[] => {
      const text = outputs[w.id]
      if (!text) return []
      if (text.startsWith('…')) return [<Text key={`${w.id}-busy`} dimColor>{text}</Text>]
      return [
        <Markdown key={`${w.id}-ans`} text={text} />,
        <Box key={`${w.id}-ansbtn`} gap={1}>
          <Button key={`${w.id}-copy`} label="Copy" plain onPress={() => void copy($, text)} />
          <Button key={`${w.id}-fill`} label="To prompt" plain onPress={() => void $.prompt.fill({ text, mode: 'insert' })} />
          <Button key={`${w.id}-clr`} label="×" plain onPress={() => void setOutput($, w.id, '')} />
        </Box>,
      ]
    }

    for (const w of PANEL.widgets) {
      const rows: RenderChildren[] = []
      switch (w.kind) {
        case 'note':
          if (w.title) rows.push(head(w, 'text'))
          rows.push(<Markdown key={`${w.id}-md`} text={w.text} />)
          break

        case 'agents': {
          const all = await read($, S_agents)
          const list = all.filter(a => w.showDone || !ENDED.includes(a.status))
          const running = list.filter(a => !ENDED.includes(a.status)).length
          rows.push(head(w, 'claude', ` · ${running} running`))
          if (!list.length) rows.push(<Text key={`${w.id}-none`} dimColor>No agents.</Text>)
          for (const a of list) {
            const took = a.durationMs ?? (a.endedMs ?? now) - a.firstSeenMs
            const meta = [a.type, a.model, a.status, `⏱ ${dur(took)}`, `ctx ${tok(a.ctxTokens)}`, `out ${tok(a.outTokens)}`, `${a.tools} tools`]
              .filter(Boolean)
              .join(' · ')
            rows.push(
              <Box key={`${w.id}-${a.id}`} flexDirection="column">
                <Box gap={1}>
                  <Text color={a.status === 'failed' ? 'error' : ENDED.includes(a.status) ? 'subtle' : 'suggestion'}>{GLYPH[a.status] ?? '·'}</Text>
                  <Text wrap="truncate-end">{a.description}</Text>
                  <Button
                    key={`${w.id}-${a.id}-view`}
                    label="Open"
                    plain
                    onPress={async () => {
                      const r = await $.ui.view({ agentId: a.id })
                      if (r.deny) await flash($, `Cannot open: ${r.deny}`)
                    }}
                  />
                </Box>
                <Text dimColor wrap="truncate-end">
                  {'  '}
                  {meta}
                  {a.lastTool && !ENDED.includes(a.status) ? ` · ${a.lastTool}` : ''}
                </Text>
              </Box>,
            )
          }
          if (w.allowMessage && Input && Select && all.length) {
            const to = drafts[`${w.id}:to`] ?? all[0]!.id
            rows.push(
              <Select key={`${w.id}-to`} label="To agent" value={to} options={all.map(a => ({ value: a.id, label: clip(a.description, 40) }))} onSelect={setDraft(`${w.id}:to`)} />,
              <Input
                key={`${w.id}-msg`}
                label="Message"
                placeholder="Enter to send to the agent"
                value={drafts[`${w.id}:msg`] ?? ''}
                onInput={setDraft(`${w.id}:msg`)}
                onSubmit={async text => {
                  if (!text.trim()) return
                  try {
                    await $.session.send({ to: { agentId: to }, text })
                    await clearDraft(`${w.id}:msg`)
                    await flash($, 'Sent to the agent')
                  } catch (err) {
                    await flash($, `Not sent: ${String(err)}`)
                  }
                }}
              />,
            )
          }
          break
        }

        case 'spawn': {
          rows.push(head(w, 'suggestion'))
          if (w.presets.length)
            rows.push(
              <Box key={`${w.id}-presets`} gap={1} flexWrap="wrap">
                {w.presets.map((p, i) => (
                  <Button key={`${w.id}-p${i}`} label={p.label} onPress={() => void spawn($, p)} />
                ))}
              </Box>,
            )
          if (w.freeInput && Input) {
            const types = w.types.split(',').map(s => s.trim()).filter(Boolean)
            const type = drafts[`${w.id}:type`] ?? types[0] ?? 'general-purpose'
            if (Select && types.length > 1)
              rows.push(<Select key={`${w.id}-type`} label="Type" value={type} options={types.map(t => ({ value: t, label: t }))} onSelect={setDraft(`${w.id}:type`)} />)
            rows.push(
              <Input
                key={`${w.id}-prompt`}
                label="Task"
                placeholder="What should the agent do? Enter to start"
                value={drafts[`${w.id}:prompt`] ?? ''}
                onInput={setDraft(`${w.id}:prompt`)}
                onSubmit={async v => {
                  await clearDraft(`${w.id}:prompt`)
                  await spawn($, { label: v.slice(0, 40), type, prompt: v })
                }}
              />,
            )
          }
          break
        }

        case 'agentTypes':
          rows.push(head(w, 'suggestion', ` · ${w.presets.length}`))
          for (const [i, a] of w.presets.entries())
            rows.push(
              <Box key={`${w.id}-${i}`} gap={1}>
                <Button
                  key={`${w.id}-${i}-run`}
                  label={`▶ ${a.name}`}
                  plain
                  onPress={() => void spawn($, { label: a.name, type: `${PANEL.name}:${a.name}`, prompt: drafts[`${w.id}:task`] || a.description })}
                />
                <Text dimColor wrap="truncate-end">
                  {a.description}
                  {a.model ? ` · ${a.model}` : ''}
                </Text>
              </Box>,
            )
          if (Input && w.presets.length)
            rows.push(
              <Input
                key={`${w.id}-task`}
                label="Task for ▶"
                placeholder="optional: otherwise the agent gets its description"
                value={drafts[`${w.id}:task`] ?? ''}
                onInput={setDraft(`${w.id}:task`)}
                onSubmit={setDraft(`${w.id}:task`)}
              />,
            )
          break

        case 'sessions': {
          const peers = (await read($, S_peers)).filter(p => !(w.hideSelf && p.isSelf))
          rows.push(head(w, 'remember', ` · ${peers.length}`))
          if (outputs.peers) rows.push(<Text key={`${w.id}-err`} color="error">{outputs.peers}</Text>)
          if (!peers.length) rows.push(<Text key={`${w.id}-none`} dimColor>No other sessions.</Text>)
          for (const p of peers)
            rows.push(
              <Box key={`${w.id}-${p.pid}`} gap={1}>
                <Text color={p.status === 'busy' ? 'warning' : 'success'}>{p.status === 'busy' ? '◐' : '●'}</Text>
                <Text bold={p.isSelf}>{p.name}</Text>
                <Text dimColor wrap="truncate-end">
                  {p.status} · {tilde(p.cwd, home)} · {dur(now - p.updatedAt)} ago{p.isSelf ? ' · this one' : ''}
                </Text>
              </Box>,
            )
          if (w.allowSend && Input && Select && peers.some(p => !p.isSelf)) {
            const others = peers.filter(p => !p.isSelf)
            const to = drafts[`${w.id}:to`] ?? others[0]!.sessionId
            rows.push(
              <Select key={`${w.id}-to`} label="To" value={to} options={others.map(p => ({ value: p.sessionId, label: p.name }))} onSelect={setDraft(`${w.id}:to`)} />,
              <Input
                key={`${w.id}-msg`}
                label="Message"
                placeholder="Enter to send"
                value={drafts[`${w.id}:msg`] ?? ''}
                onInput={setDraft(`${w.id}:msg`)}
                onSubmit={async text => {
                  if (!text.trim()) return
                  try {
                    await $.session.send({ to: { sessionId: to }, text })
                    await clearDraft(`${w.id}:msg`)
                    await flash($, 'Sent')
                  } catch (err) {
                    await flash($, `Not sent: ${String(err)}`)
                  }
                }}
              />,
            )
          }
          break
        }

        case 'newSession':
          rows.push(head(w, 'claude'))
          rows.push(
            <Box key={`${w.id}-row`} gap={1}>
              <Button key={`${w.id}-open`} label={w.label || 'New session'} variant="primary" onPress={() => void openSession($, w, drafts[`${w.id}:prompt`] ?? w.prompt)} />
              <Text dimColor>
                {w.app}
                {w.cwd ? ` · ${w.cwd}` : ' · this folder'}
              </Text>
            </Box>,
          )
          if (Input)
            rows.push(
              <Input
                key={`${w.id}-prompt`}
                label="First prompt"
                placeholder={w.prompt || 'optional'}
                value={drafts[`${w.id}:prompt`] ?? ''}
                onInput={setDraft(`${w.id}:prompt`)}
                onSubmit={v => void openSession($, w, v || w.prompt)}
              />,
            )
          break

        case 'control': {
          const turn = await read($, S_turn)
          rows.push(head(w, 'warning', turn ? ` · working ${dur(now - turn.startedMs)}` : ' · idle'))
          rows.push(
            <Box key={`${w.id}-row`} gap={1}>
              {w.stop && turn && (
                <Button
                  key={`${w.id}-stop`}
                  label="■ Stop"
                  variant="primary"
                  onPress={async () => {
                    await $.turn.abort({ turnId: turn.id })
                    await flash($, 'Turn stopped')
                  }}
                />
              )}
              {w.compact && (
                <Button
                  key={`${w.id}-compact`}
                  label="Compact"
                  onPress={async () => {
                    const instructions = drafts[`${w.id}:compact`]?.trim()
                    await flash($, 'Compacting…')
                    await $.session.compact(instructions ? { instructions } : undefined)
                    await clearDraft(`${w.id}:compact`)
                    await flash($, 'Context compacted')
                    void refreshUsage($)
                  }}
                />
              )}
              {w.clear && <Button key={`${w.id}-clear`} label="/clear" onPress={() => void $.command.run({ command: 'clear' })} />}
            </Box>,
          )
          if (w.compact && Input)
            rows.push(
              <Input
                key={`${w.id}-cinstr`}
                label="What to keep when compacting"
                placeholder="optional"
                value={drafts[`${w.id}:compact`] ?? ''}
                onInput={setDraft(`${w.id}:compact`)}
                onSubmit={setDraft(`${w.id}:compact`)}
              />,
            )
          break
        }

        case 'messages': {
          const list = (await read($, S_messages)).slice(-w.count)
          rows.push(head(w, 'text'))
          if (!list.length) rows.push(<Text key={`${w.id}-none`} dimColor>The conversation is empty.</Text>)
          for (const [i, m] of list.entries())
            rows.push(
              <Box key={`${w.id}-${i}`} gap={1}>
                <Text color={m.role === 'user' ? 'suggestion' : 'claude'}>{m.role === 'user' ? '›' : '◆'}</Text>
                <Text wrap="truncate-end">{m.text || `(${m.tools.join(', ')})`}</Text>
                {m.text && m.tools.length > 0 && <Text dimColor>· {m.tools.length} tools</Text>}
              </Box>,
            )
          break
        }

        case 'usage': {
          const u = await read($, S_usage)
          rows.push(head(w, 'permission'))
          if (!u) {
            rows.push(<Text key={`${w.id}-none`} dimColor>No data.</Text>)
            break
          }
          const pct = u.percent ?? 0
          rows.push(
            <Text key={`${w.id}-ctx`}>
              <Text color={pct > 80 ? 'error' : pct > 60 ? 'warning' : 'success'}>{bar(pct)}</Text> context {Math.round(pct)}% · {tok(u.tokens)} / {tok(u.window)}
            </Text>,
          )
          if (w.showCost && u.usd !== undefined) rows.push(<Text key={`${w.id}-usd`}>cost ${u.usd.toFixed(2)}</Text>)
          if (w.showLimits)
            for (const l of u.limits)
              rows.push(
                <Text key={`${w.id}-${l.kind}`}>
                  <Text color={l.percentUsed > 80 ? 'error' : 'subtle'}>{bar(l.percentUsed)}</Text> {l.kind} {Math.round(l.percentUsed)}%
                  {l.resetsAt ? ` · resets ${l.resetsAt}` : ''}
                </Text>,
              )
          break
        }

        case 'contextChart': {
          const hist = (await read($, S_ctxHistory)).slice(-w.points)
          const last = hist[hist.length - 1]
          rows.push(head(w, 'permission', last !== undefined ? ` · ${Math.round(last)}%` : ''))
          if (hist.length) rows.push(<Text key={`${w.id}-spark`} color={last !== undefined && last > 80 ? 'error' : 'success'}>{sparkline(hist)}</Text>)
          else rows.push(<Text key={`${w.id}-none`} dimColor>fills in as turns go…</Text>)
          break
        }

        case 'session': {
          const i = await read($, S_info)
          const u = await read($, S_usage)
          rows.push(head(w, 'text'))
          if (i)
            rows.push(
              <Text key={`${w.id}-row`} wrap="truncate-end">
                {i.model} · {i.turns} turns
                {u ? ` · ${dur(now - u.startedAt)}` : ''} · {tilde(i.cwd, home)}
              </Text>,
            )
          break
        }

        case 'git': {
          const g = await read($, S_git)
          rows.push(head(w, 'merged'))
          if (!g) break
          if (g.error) {
            rows.push(<Text key={`${w.id}-err`} dimColor>{g.error}</Text>)
            break
          }
          rows.push(
            <Text key={`${w.id}-br`}>
              <Text bold>{g.branch}</Text>
              {g.ahead ? <Text color="success"> ↑{g.ahead}</Text> : ''}
              {g.behind ? <Text color="warning"> ↓{g.behind}</Text> : ''} · {g.files.length ? `${g.files.length} changed` : 'clean'}
            </Text>,
          )
          for (const f of g.files.slice(0, w.maxFiles))
            rows.push(
              <Text key={`${w.id}-f-${f}`} color={f.startsWith('??') ? 'subtle' : f.includes('D') ? 'diffRemoved' : 'diffAdded'} wrap="truncate-end">
                {'  '}
                {f}
              </Text>,
            )
          if (g.files.length > w.maxFiles) rows.push(<Text key={`${w.id}-more`} dimColor>{`  …${g.files.length - w.maxFiles} more`}</Text>)
          if (g.last) rows.push(<Text key={`${w.id}-last`} dimColor wrap="truncate-end">{g.last}</Text>)
          break
        }

        case 'diff': {
          const d = outputs[w.id] ?? ''
          rows.push(
            <Box key={`${w.id}-h`} gap={1}>
              <Text bold color="merged">
                {w.title}
              </Text>
              <Button key={`${w.id}-r`} label="↻" plain onPress={() => void refreshDiff($, w)} />
            </Box>,
          )
          if (d.startsWith('!')) rows.push(<Text key={`${w.id}-err`} dimColor>{d.slice(1)}</Text>)
          else if (!d.trim()) rows.push(<Text key={`${w.id}-none`} dimColor>No changes.</Text>)
          else rows.push(<Code key={`${w.id}-code`} source={d} format="diff" />)
          break
        }

        case 'tools': {
          const list = (await read($, S_tools)).filter(t => !w.agentsOnly || t.agentId).slice(-w.count)
          rows.push(head(w, 'bashBorder'))
          if (!list.length) rows.push(<Text key={`${w.id}-none`} dimColor>No tool calls yet.</Text>)
          for (const t of list)
            rows.push(
              <Box key={`${w.id}-${t.id}`} gap={1}>
                <Text color={t.denied || t.isError ? 'error' : t.endedMs ? 'success' : 'suggestion'}>{t.denied ? '⊘' : t.isError ? '✗' : t.endedMs ? '✓' : '◐'}</Text>
                <Text bold>{t.tool}</Text>
                <Text dimColor wrap="truncate-end">
                  {t.detail} · {dur((t.endedMs ?? now) - t.startedMs)}
                  {t.agentId ? ' · agent' : ''}
                </Text>
              </Box>,
            )
          break
        }

        case 'inventory': {
          const inv = await read($, S_inventory)
          const isOpen = !!expanded[w.id]
          rows.push(
            <Box key={`${w.id}-h`} gap={1}>
              <Text bold color="text">
                {w.title}
              </Text>
              {inv && (
                <Text dimColor>
                  {inv.tools.length} tools ({inv.tools.filter(t => t.mcp).length} MCP) · {inv.commands.length} commands
                </Text>
              )}
              <Button key={`${w.id}-tg`} label={isOpen ? 'hide' : 'list'} plain onPress={() => void update($, S_expanded, x => ({ ...x, [w.id]: !isOpen }))} />
              <Button key={`${w.id}-r`} label="↻" plain onPress={() => void refreshInventory($)} />
            </Box>,
          )
          if (inv && isOpen) {
            rows.push(<Text key={`${w.id}-tools`} wrap="wrap">{inv.tools.map(t => t.name).join(', ')}</Text>)
            rows.push(<Text key={`${w.id}-cmds`} dimColor wrap="wrap">{inv.commands.map(c => `/${c.name}`).join('  ')}</Text>)
          }
          break
        }

        case 'ask':
          rows.push(head(w, 'claude'))
          if (w.presets.length)
            rows.push(
              <Box key={`${w.id}-presets`} gap={1} flexWrap="wrap">
                {w.presets.map((p, i) => (
                  <Button key={`${w.id}-p${i}`} label={p.label} onPress={() => void askSession($, w.id, p.question)} />
                ))}
              </Box>,
            )
          if (w.freeInput && Input)
            rows.push(
              <Input
                key={`${w.id}-q`}
                label="Question"
                placeholder="Ask about this session… Enter"
                value={drafts[`${w.id}:q`] ?? ''}
                onInput={setDraft(`${w.id}:q`)}
                onSubmit={async q => {
                  await clearDraft(`${w.id}:q`)
                  await askSession($, w.id, q)
                }}
              />,
            )
          rows.push(...answer(w))
          break

        case 'aiAction':
          rows.push(head(w, 'claude'))
          rows.push(
            <Box key={`${w.id}-presets`} gap={1} flexWrap="wrap">
              {w.presets.map((p, i) => (
                <Button key={`${w.id}-p${i}`} label={p.label} onPress={() => void runAi($, w.id, p)} />
              ))}
            </Box>,
          )
          rows.push(...answer(w))
          break

        case 'nextStep': {
          const s = outputs[w.id]
          rows.push(
            <Box key={`${w.id}-h`} gap={1}>
              <Text bold color="claude">
                {w.title}
              </Text>
              {toggle(w)}
              <Button key={`${w.id}-now`} label="↻" plain onPress={() => void suggestNext($, w)} />
            </Box>,
          )
          if (s)
            rows.push(
              <Box key={`${w.id}-s`} gap={1}>
                <Text wrap="truncate-end">{s}</Text>
                <Button key={`${w.id}-ins`} label="Insert" plain onPress={() => void $.prompt.fill({ text: s, mode: 'replace' })} />
              </Box>,
            )
          else rows.push(<Text key={`${w.id}-none`} dimColor>Shows up after Claude’s next answer.</Text>)
          break
        }

        case 'selection':
          rows.push(head(w, 'suggestion'))
          if (w.quote) rows.push(<Button key={`${w.id}-quote`} label="Quote the selection into the prompt" onPress={() => void quoteSelection($)} />)
          if (w.ask && Input)
            rows.push(
              <Input
                key={`${w.id}-q`}
                label="Ask about the selection"
                placeholder="What does this do? Enter"
                value={drafts[`${w.id}:q`] ?? ''}
                onInput={setDraft(`${w.id}:q`)}
                onSubmit={async q => {
                  const sel = await $.ui.selection()
                  if (!sel) return flash($, 'Nothing selected')
                  await clearDraft(`${w.id}:q`)
                  await askSession($, w.id, `${q || 'Explain'}:\n\n${sel.text}`)
                }}
              />,
            )
          rows.push(...answer(w))
          break

        case 'prompts':
          rows.push(head(w, 'suggestion'))
          rows.push(
            <Box key={`${w.id}-row`} gap={1} flexWrap="wrap">
              {w.presets.map((p, i) => (
                <Button
                  key={`${w.id}-p${i}`}
                  label={p.label}
                  onPress={async () => {
                    if (p.mode === 'submit') {
                      void $.prompt.submit({ text: p.text })
                      await flash($, `Sent: ${p.label}`)
                    } else await $.prompt.fill({ text: p.text, mode: 'insert' })
                  }}
                />
              ))}
            </Box>,
          )
          break

        case 'commands': {
          rows.push(head(w, 'suggestion'))
          if (w.presets.length)
            rows.push(
              <Box key={`${w.id}-row`} gap={1} flexWrap="wrap">
                {w.presets.map((p, i) => (
                  <Button
                    key={`${w.id}-c${i}`}
                    label={p.label || `/${p.command}`}
                    onPress={async () => {
                      const r = await $.command.run({ command: p.command.replace(/^\//, ''), args: p.args })
                      if (r.text) await flash($, r.text.split('\n')[0] ?? '')
                    }}
                  />
                ))}
              </Box>,
            )
          const inv = await read($, S_inventory)
          if (w.picker && Select && inv?.commands.length) {
            const cmd = drafts[`${w.id}:cmd`] ?? inv.commands[0]!.name
            rows.push(
              <Box key={`${w.id}-pick`} gap={1}>
                <Select
                  key={`${w.id}-sel`}
                  label="Any command"
                  value={cmd}
                  options={inv.commands.map(c => ({ value: c.name, label: `/${c.name}` }))}
                  onSelect={setDraft(`${w.id}:cmd`)}
                />
                <Button
                  key={`${w.id}-go`}
                  label="Run"
                  onPress={async () => {
                    const r = await $.command.run({ command: cmd })
                    if (r.text) await flash($, r.text.split('\n')[0] ?? '')
                  }}
                />
              </Box>,
            )
            const desc = inv.commands.find(c => c.name === cmd)?.description
            if (desc) rows.push(<Text key={`${w.id}-desc`} dimColor wrap="truncate-end">{desc}</Text>)
          }
          break
        }

        case 'choice':
          rows.push(head(w, 'suggestion'))
          rows.push(<Button key={`${w.id}-ask`} label={w.label || w.question} onPress={() => void runChoice($, w)} />)
          break

        case 'snippets':
          rows.push(head(w, 'suggestion'))
          rows.push(
            <Box key={`${w.id}-row`} gap={1} flexWrap="wrap">
              {w.presets.map((p, i) => (
                <Button key={`${w.id}-s${i}`} label={`⧉ ${p.label}`} onPress={() => void copy($, p.text)} />
              ))}
            </Box>,
          )
          break

        case 'shell': {
          const isOpen = expanded[w.id] !== false
          rows.push(
            <Box key={`${w.id}-h`} gap={1}>
              <Text bold color="bashBorder">
                {w.title}
              </Text>
              <Text dimColor wrap="truncate-end">
                $ {w.command}
              </Text>
              <Button key={`${w.id}-run`} label="↻" plain onPress={() => void refreshShell($, w)} />
              <Button key={`${w.id}-tg`} label={isOpen ? '−' : '+'} plain onPress={() => void update($, S_expanded, x => ({ ...x, [w.id]: !isOpen }))} />
            </Box>,
          )
          if (isOpen) rows.push(<Text key={`${w.id}-out`}>{outputs[w.id] ?? '…'}</Text>)
          break
        }

        case 'file':
          rows.push(head(w, 'text', ` · ${w.path}`))
          rows.push(<Text key={`${w.id}-out`}>{outputs[w.id] ?? '…'}</Text>)
          break

        case 'image': {
          rows.push(head(w, 'text'))
          const path = await cwdPath($, w.path)
          if (Image) rows.push(<Image key={`${w.id}-img`} source={{ file: path, format: 'png' }} columns={w.columns} rows={w.rows} alt={w.path} />)
          else rows.push(<Text key={`${w.id}-alt`} dimColor>{w.path}</Text>)
          break
        }

        case 'links':
          rows.push(head(w, 'suggestion'))
          for (const [i, l] of w.presets.entries()) rows.push(<Link key={`${w.id}-l${i}`} href={l.url} label={l.label || l.url} />)
          break

        case 'http':
          rows.push(
            <Box key={`${w.id}-h`} gap={1}>
              <Text bold color="remember">
                {w.title}
              </Text>
              <Button key={`${w.id}-r`} label="↻" plain onPress={() => void refreshHttp($, w)} />
            </Box>,
          )
          rows.push(<Text key={`${w.id}-out`} wrap="wrap">{outputs[w.id] ?? '…'}</Text>)
          break

        case 'mcp':
          rows.push(
            <Box key={`${w.id}-h`} gap={1}>
              <Text bold color="remember">
                {w.title}
              </Text>
              <Text dimColor>
                {w.server} · {w.tool}
              </Text>
              <Button key={`${w.id}-r`} label="↻" plain onPress={() => void refreshMcp($, w)} />
            </Box>,
          )
          rows.push(<Text key={`${w.id}-out`} wrap="wrap">{outputs[w.id] ?? '…'}</Text>)
          break

        case 'notes': {
          const notes = (await read($, S_notes))[w.id] ?? []
          rows.push(head(w, 'warning', ` · ${notes.length}`))
          for (const [i, n] of notes.entries())
            rows.push(
              <Box key={`${w.id}-${i}`} gap={1}>
                <Text>• {n}</Text>
                <Button key={`${w.id}-${i}-x`} label="×" plain onPress={() => void setNotes($, w.id, notes.filter((_, j) => j !== i))} />
              </Box>,
            )
          if (Input)
            rows.push(
              <Input
                key={`${w.id}-add`}
                label="Note"
                placeholder="Kept across sessions. Enter"
                value={drafts[`${w.id}:add`] ?? ''}
                onInput={setDraft(`${w.id}:add`)}
                onSubmit={async text => {
                  if (!text.trim()) return
                  await clearDraft(`${w.id}:add`)
                  await setNotes($, w.id, [...notes, text.trim()])
                }}
              />,
            )
          break
        }

        case 'voice':
          rows.push(
            <Box key={`${w.id}-h`} gap={1}>
              <Text bold color="claude">
                {w.title}
              </Text>
              {toggle(w)}
            </Box>,
          )
          rows.push(
            <Text key={`${w.id}-d`} dimColor wrap="truncate-end">
              turns over {w.minSeconds}s →{w.speak ? ` say “${w.speak}”` : ''}
              {w.notify ? ' + notification' : ''}
            </Text>,
          )
          break

        case 'guard':
          rows.push(
            <Box key={`${w.id}-h`} gap={1}>
              <Text bold color="error">
                {w.title}
              </Text>
              {toggle(w)}
              <Text dimColor>blocked: {counters[w.id] ?? 0}</Text>
            </Box>,
          )
          for (const [i, r] of w.rules.entries())
            rows.push(
              <Text key={`${w.id}-${i}`} dimColor wrap="truncate-end">
                {'  '}
                {r.tool || '*'} ~ /{r.pattern}/ → {r.reason}
              </Text>,
            )
          break

        case 'systemPrompt':
          rows.push(
            <Box key={`${w.id}-h`} gap={1}>
              <Text bold color="permission">
                {w.title}
              </Text>
              {toggle(w)}
            </Box>,
          )
          rows.push(<Text key={`${w.id}-t`} dimColor wrap="truncate-end">{clip(w.text, 200)}</Text>)
          break

        case 'modelTool':
          rows.push(
            <Box key={`${w.id}-h`} gap={1}>
              <Text bold color="bashBorder">
                {w.title}
              </Text>
              <Text dimColor>
                {TOOL_PREFIX}
                {w.name} · {counters[w.id] ?? 0} calls
              </Text>
            </Box>,
          )
          rows.push(<Text key={`${w.id}-cmd`} dimColor wrap="truncate-end">$ {w.command}</Text>)
          break
      }
      sections.push(
        <Box key={w.id} flexDirection="column">
          {rows}
        </Box>,
      )
    }

    const msg = await read($, S_flash)
    sections.push(
      <Text key="footer" dimColor>
        {msg ? `${msg} · ` : ''}refreshes every {PANEL.refreshSec}s
      </Text>,
    )
    return (
      <Box flexDirection="column" gap={1}>
        {sections}
      </Box>
    )
  })

  if (PANEL.band)
    on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
      if (e.props.hasSurvey) return next(e)
      const { Box, Text, Button } = $.ui.resolve(e)
      const agents = (await read($, S_agents)).filter(a => !ENDED.includes(a.status))
      const u = await read($, S_usage)
      const g = await read($, S_git)
      const parts: string[] = []
      if (agents.length) parts.push(`◐ ${agents.length} agent${agents.length === 1 ? '' : 's'}`)
      if (u?.percent !== undefined) parts.push(`ctx ${Math.round(u.percent)}%`)
      if (g?.branch) parts.push(`${g.branch}${g.files.length ? ` ±${g.files.length}` : ''}`)
      return (
        <Box gap={1}>
          <Text bold color="claude">
            {PANEL.title}
          </Text>
          <Text dimColor>{parts.join(' · ') || '—'}</Text>
          <Button key="open" label="Open" plain onPress={() => void $.ui.open({ id: PANE, title: PANEL.title })} />
        </Box>
      )
    })
}
